function record(id: string, guestId = 1): ProcessRecord {
  return {
    owner: { guestId, appId: "fixture", revision: "r1" },
    processId: id,
    status: "exited",
    startedAt: 0,
    exitedAt: 1,
    cancelRequested: false,
